ALTER TABLE "Supplier" ADD COLUMN "supplierType" "GreenCoffeeSupplierType" NOT NULL DEFAULT 'COMPANY', ADD COLUMN "legalName" TEXT, ADD COLUMN "stateRegistration" TEXT, ADD COLUMN "ruralRegistration" TEXT, ADD COLUMN "farmName" TEXT, ADD COLUMN "country" TEXT DEFAULT 'Brasil', ADD COLUMN "address" TEXT, ADD COLUMN "contactName" TEXT, ADD COLUMN "contactPhone" TEXT, ADD COLUMN "contactEmail" TEXT;
ALTER TABLE "GreenCoffeeReceipt" ADD COLUMN "purchaseId" TEXT, ADD COLUMN "packagingType" "GreenCoffeePackagingType" NOT NULL DEFAULT 'OTHER', ADD COLUMN "volumeQuantity" INTEGER, ADD COLUMN "nominalWeightKg" DECIMAL(14,3), ADD COLUMN "sampleCollected" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "visualCondition" TEXT, ADD COLUMN "approvalStatus" "GreenCoffeeApprovalStatus";

CREATE TABLE "GreenCoffeePurchase" ("id" TEXT NOT NULL,"companyId" TEXT NOT NULL,"supplierId" TEXT NOT NULL,"purchaseNumber" TEXT NOT NULL,"status" "GreenCoffeePurchaseStatus" NOT NULL DEFAULT 'DRAFT',"purchasedAt" TIMESTAMP(3) NOT NULL,"buyerId" TEXT NOT NULL,"buyerName" TEXT NOT NULL,"species" TEXT NOT NULL,"originRegion" TEXT NOT NULL,"municipality" TEXT,"state" TEXT,"country" TEXT NOT NULL DEFAULT 'Brasil',"farmName" TEXT,"harvest" TEXT NOT NULL,"variety" TEXT,"process" TEXT,"supplierLotCode" TEXT,"qualityDescription" TEXT,"contractedScreen" TEXT,"maxDefects" INTEGER,"maxMoisturePercent" DECIMAL(5,2),"beverageClassification" TEXT,"minimumScore" DECIMAL(5,2),"technicalSpecifications" TEXT,"packagingType" "GreenCoffeePackagingType" NOT NULL,"volumeQuantity" INTEGER NOT NULL,"nominalUnitWeightKg" DECIMAL(14,3) NOT NULL,"contractedWeightKg" DECIMAL(14,3) NOT NULL,"weightTolerancePercent" DECIMAL(7,3) NOT NULL DEFAULT 0,"pricePerKg" DECIMAL(14,4),"pricePerBag" DECIMAL(14,2),"currency" TEXT NOT NULL DEFAULT 'BRL',"totalValue" DECIMAL(14,2) NOT NULL,"paymentTerms" TEXT,"expectedAt" TIMESTAMP(3),"commercialNotes" TEXT,"idempotencyKey" TEXT NOT NULL,"confirmedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GreenCoffeePurchase_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GreenCoffeeLabSample" ("id" TEXT NOT NULL,"receiptId" TEXT NOT NULL,"sampleNumber" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GreenCoffeeLabSample_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GreenCoffeeApprovalRequest" ("id" TEXT NOT NULL,"companyId" TEXT NOT NULL,"purchaseId" TEXT NOT NULL,"receiptId" TEXT NOT NULL,"status" "GreenCoffeeApprovalStatus" NOT NULL DEFAULT 'PENDING',"requiredRole" TEXT NOT NULL,"reason" TEXT NOT NULL,"differences" JSONB NOT NULL,"decidedById" TEXT,"decidedByName" TEXT,"justification" TEXT,"decidedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GreenCoffeeApprovalRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OperationalNotification" ("id" TEXT NOT NULL,"companyId" TEXT NOT NULL,"purchaseId" TEXT,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"targetRole" TEXT NOT NULL,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OperationalNotification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GreenCoffeeAuditEvent" ("id" TEXT NOT NULL,"companyId" TEXT NOT NULL,"purchaseId" TEXT,"receiptId" TEXT,"action" TEXT NOT NULL,"actorId" TEXT NOT NULL,"actorName" TEXT NOT NULL,"metadata" JSONB,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GreenCoffeeAuditEvent_pkey" PRIMARY KEY ("id"));

