CREATE INDEX "GreenCoffeeApprovalRequest_companyId_status_idx" ON "GreenCoffeeApprovalRequest"("companyId","status"); CREATE INDEX "GreenCoffeeApprovalRequest_receiptId_idx" ON "GreenCoffeeApprovalRequest"("receiptId"); CREATE INDEX "OperationalNotification_companyId_readAt_idx" ON "OperationalNotification"("companyId","readAt"); CREATE INDEX "GreenCoffeeAuditEvent_companyId_occurredAt_idx" ON "GreenCoffeeAuditEvent"("companyId","occurredAt"); CREATE INDEX "GreenCoffeeAuditEvent_purchaseId_idx" ON "GreenCoffeeAuditEvent"("purchaseId"); CREATE INDEX "GreenCoffeeAuditEvent_receiptId_idx" ON "GreenCoffeeAuditEvent"("receiptId"); CREATE INDEX "GreenCoffeeReceipt_purchaseId_idx" ON "GreenCoffeeReceipt"("purchaseId");

